actions.script:
const L = (text) => ec.l10n.localize(text)
url = String(url || '').trim()
if (url && !/^[a-z]+:\/\//i.test(url)) url = 'https://' + url
const pairingCode = String(code || '').trim()
if (!url) { ec.message.addError(L('Enter the edge node address')); return }
if (!pairingCode) { ec.message.addError(L('Enter the pairing code made on the edge node')); return }
const out = ec.service.sync().name('org.moqui.edge.EdgeServices.check#EdgeNode').parameter('url', url).call() || {}
if (ec.message.hasError()) return
ec.web.sessionAttributes.edgePairingCode = pairingCode
// for Connect: what the edge node answered, for this address (session attributes are text)
ec.web.sessionAttributes.edgeCheck = JSON.stringify({url: url, edgeName: out.edgeName || '', fingerprint: out.fingerprint || '',
    binaryVersion: out.binaryVersion || '', linkVersion: out.linkVersion ? String(out.linkVersion) : '',
    publicNames: Array.from(out.publicNames || []).map(String), features: Array.from(out.features || []).map(String),
    compatible: out.compatible !== false, message: out.message || ''})

const link = ec.service.sync().name('org.moqui.edge.EdgeServices.get#LinkStatus').call() || {}
notBuilt = link.state === 'notBuilt'
notStarted = link.state === 'notStarted'
const running = !notBuilt && !notStarted
// an edge or all-in-one node takes links; the wizard is a local node's (plans/archive/Edge-Node.md §10)
isEdge = running && link.takesLinks === true
alreadyPaired = running && !isEdge && !!link.state && link.state !== 'unpaired'
pairedName = link.edgeName || link.url || ''
canPair = running && !isEdge && !alreadyPaired
edgeAddress = {url: url || ''}
